const socialReactions = `-- name: SocialReactions :many
SELECT r.owner_id, r.title_id, r.day::text AS day, r.emoji, count(*)::int AS count,
    bool_or(r.user_id = $1::uuid)::bool AS mine
FROM social_reactions r
WHERE r.owner_id = ANY($2::uuid[]) AND r.title_id = ANY($3::uuid[])
  AND r.day::text = ANY($4::text[])
GROUP BY r.owner_id, r.title_id, r.day, r.emoji
`

type SocialReactionsParams struct {
	Viewer uuid.UUID
	Owners []uuid.UUID
	Titles []uuid.UUID
	Days   []string
}

type SocialReactionsRow struct {
	OwnerID uuid.UUID
	TitleID uuid.UUID
	Day     string
	Emoji   string
	Count   int32
	Mine    bool
}

// Each column against its own list; the service keeps only the exact (owner, title, day) keys
// (sqlc cannot read a multi-array unnest).
func (q *Queries) SocialReactions(ctx context.Context, arg SocialReactionsParams) ([]SocialReactionsRow, error) {
	rows, err := q.db.Query(ctx, socialReactions,
		arg.Viewer,
		arg.Owners,
		arg.Titles,
		arg.Days,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SocialReactionsRow{}
	for rows.Next() {
		var i SocialReactionsRow
		if err := rows.Scan(
			&i.OwnerID,
			&i.TitleID,
			&i.Day,
			&i.Emoji,
			&i.Count,
			&i.Mine,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

