const socialRedeemInvite = `-- name: SocialRedeemInvite :one
UPDATE social_invites SET redeemed_by = $1::uuid, redeemed_at = $2
WHERE code = $3 AND inviter_id <> $1::uuid
  AND redeemed_at IS NULL AND revoked_at IS NULL AND expires_at > $2
RETURNING inviter_id
`

type SocialRedeemInviteParams struct {
	Redeemer uuid.UUID
	Now      *time.Time
	Code     string
}

// The conditional update is the lock: of two people opening one link at once, one wins.
func (q *Queries) SocialRedeemInvite(ctx context.Context, arg SocialRedeemInviteParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, socialRedeemInvite, arg.Redeemer, arg.Now, arg.Code)
	var inviter_id uuid.UUID
	err := row.Scan(&inviter_id)
	return inviter_id, err
}

