const socialTheyLoved = `-- name: SocialTheyLoved :many
SELECT a.title_id FROM library_items a
WHERE a.user_id = $1::uuid AND a.rating >= 8
  AND NOT EXISTS (
      SELECT 1 FROM library_items b WHERE b.user_id = $2::uuid AND b.title_id = a.title_id
  )
ORDER BY a.rating DESC, a.finished_at DESC NULLS LAST LIMIT $3
`

type SocialTheyLovedParams struct {
	Owner   uuid.UUID
	Viewer  uuid.UUID
	MaxRows int32
}

func (q *Queries) SocialTheyLoved(ctx context.Context, arg SocialTheyLovedParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, socialTheyLoved, arg.Owner, arg.Viewer, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var title_id uuid.UUID
		if err := rows.Scan(&title_id); err != nil {
			return nil, err
		}
		items = append(items, title_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

